INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('itel-p65-8gb-128gb-new', 'itel P65 8GB/128GB - Brand New - 6.6" 90Hz, 50MP AI Camera, 5000mAh', 'smartphones', 165000, 165000, 138000, 12, 0.20, '/assets/products/itel-p65-8gb-128gb-new.webp', 'The itel P65 delivers remarkable value with 8GB RAM and 128GB storage at an entry-level price. The 6.6-inch HD+ display provides an immersive canvas for entertainment, while the powerful processor and generous RAM ensure smooth multitasking across multiple apps. The 50MP AI dual-camera system with LED flash, massive 5000mAh battery with 18W fast charging, and premium textured back design create a compelling package for budget-conscious buyers who refuse to compromise on performance. With side fingerprint sensor, AI face unlock, and dual SIM support. Brand new, sealed, 1-year itel warranty.', 1, 1718400000, 1, 138000, '/assets/products/itel-p65-8gb-128gb-new.webp', 150000, 4.3, 0, 'itel', 0, 1, 'gadgets');

