VALUES ('google-pixel-10-128gb-new', 'Google Pixel 10 128GB - Brand New - Tensor G5, AI Camera, 7 Years Updates', 'smartphones', 1350000, 1350000, 1180000, 4, 0.19, '/assets/products/google-pixel-10-128gb-new.webp', 'The Google Pixel 10 is the purest expression of Android intelligence. Powered by Google custom Tensor G5 chip with advanced on-device AI, this device delivers computational photography that defies physics. The 6.3-inch Actua display with 120Hz refresh rate brings content to life with stunning accuracy. The pro triple-camera system with 5x optical zoom, Real Tone technology, and Magic Eraser ensures every photo is gallery-worthy. With 7 years of OS and security updates, Gemini AI integration, and pure Android 16, this is the smartphone that gets smarter every day. Features include Call Screen, Hold for Me, Live Translate, and the most advanced spam protection. Brand new, sealed, 1-year Google warranty.', 1, 1718400000, 1, 1180000, '/assets/products/google-pixel-10-128gb-new.webp', 1250000, 4.8, 1, 'Google', 1, 1, 'gadgets');

-- Oraimo 65W Fast Charger (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-65w-fast-charger-new', 'Oraimo 65W GaN Fast Charger - Brand New - USB-C PD + USB-A, Foldable Plug, Laptop Ready', 'chargers', 18000, 18000, 14500, 20, 0.12, '/assets/products/oraimo-65w-fast-charger-new.webp', 'The Oraimo 65W GaN Fast Charger is a versatile charging powerhouse compatible with smartphones, tablets, laptops, and all USB-C devices. Featuring GaN (Gallium Nitride) technology for 40% smaller size and cooler, more efficient operation, this compact charger delivers 65W of power through its USB-C PD 3.0 port and 18W through the USB-A QC 3.0 port — charge two devices simultaneously. Charges MacBook Air, iPhone 16 Pro Max, Samsung Galaxy, and all USB-C devices at full speed. The multi-protection safety system includes over-voltage, over-current, short-circuit, and temperature protection. Foldable plug for travel convenience with universal 100-240V input. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 14500, '/assets/products/oraimo-65w-fast-charger-new.webp', 16000, 4.6, 1, 'Oraimo', 1, 1, 'gadgets');

-- Oraimo Braided Data Cable 2m (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-braided-data-cable-2m-new', 'Oraimo Braided Data Cable 2m - Brand New - 100W Fast Charge, Nylon Braided, USB-C', 'accessories', 12000, 12000, 8800, 30, 0.05, '/assets/products/oraimo-braided-data-cable-2m-new.webp', 'The Oraimo Braided Data Cable 2m is engineered for durability and performance. Featuring premium nylon braiding tested to 20,000+ bend cycles, this cable outlasts standard rubber cables by 3x. The reinforced aluminum alloy connector housings with strain relief prevent fraying at stress points. The thick copper core supports 100W fast charging and 480Mbps high-speed data sync. Tangle-free design with included cable management strap. 2-meter length provides extended reach from wall outlets to beds, couches, and desks. Compatible with all USB-C smartphones, tablets, laptops, and accessories — iPhone 15/16, Samsung Galaxy, Tecno, Infinix, Xiaomi, MacBook, iPad. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 8800, '/assets/products/oraimo-braided-data-cable-2m-new.webp', 10500, 4.5, 0, 'Oraimo', 1, 0, 'gadgets');

