INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('apple-airpods-pro-3-new', 'Apple AirPods Pro 3 - Brand New - H3 Chip, Adaptive ANC 2.0, Lossless Audio', 'audio', 380000, 380000, 325000, 8, 0.056, '/assets/products/apple-airpods-pro-3-new.webp', 'The AirPods Pro 3 redefine what wireless earbuds can achieve. Featuring the next-generation H3 chip, these earbuds deliver studio-quality sound with enhanced Active Noise Cancellation, Adaptive Audio, and Personalized Spatial Audio with head tracking. The all-new design ensures an even more secure and comfortable fit with multiple ear tip sizes. The advanced health features, including hearing protection and clinical-grade hearing test capabilities, transform these from audio accessories to wellness devices. The USB-C MagSafe case with precision finding and extended battery life completes the ultimate wireless audio package. With up to 8 hours of listening time (36 hours with case), IP54 rating, and seamless Apple ecosystem integration. Brand new, sealed, original Apple packaging, 1-year Apple warranty.', 1, 1718400000, 1, 325000, '/assets/products/apple-airpods-pro-3-new.webp', 350000, 4.9, 1, 'Apple', 1, 1, 'gadgets');

