INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('itel-boxparty-speaker-new', 'itel BoxParty Bluetooth Speaker - Brand New - 40W, RGB Light Effects, IPX5, Karaoke Mic', 'audio', 100000, 100000, 85000, 10, 1.50, '/assets/products/itel-boxparty-speaker-new.webp', 'The itel BoxParty Bluetooth Speaker is a portable party powerhouse that delivers room-shaking bass and sparkling highs. Featuring a bold, boxy design with RGB light effects that pulse to your music, this speaker transforms any gathering into a celebration. The dual full-range drivers with dual passive radiators produce 40W of powerful audio, while the 8-hour battery life and TWS pairing capability for stereo sound ensure the soundtrack never stops. Includes wireless microphone for karaoke. With Bluetooth 5.3, FM radio, USB playback, AUX input, and a built-in microphone for hands-free calls. The integrated carry handle and IPX5 splash resistance make it party-ready. Brand new, sealed with full itel Nigeria warranty.', 1, 1718400000, 1, 85000, '/assets/products/itel-boxparty-speaker-new.webp', 92000, 4.5, 1, 'itel', 1, 1, 'gadgets');

-- itel Buds 5 ANC (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('itel-buds-5-anc-new', 'itel Buds 5 ANC True Wireless Earbuds - Brand New - 35dB ANC, 35H Battery, Gaming Mode', 'audio', 25000, 25000, 19000, 20, 0.045, '/assets/products/itel-buds-5-anc-new.webp', 'The itel Buds 5 ANC bring premium features to the true wireless category at an unprecedented price. Featuring Active Noise Cancellation up to 35dB with transparency mode, 10mm bio-diaphragm drivers for immersive sound, and Environmental Noise Cancellation for crystal-clear calls. The 50ms low-latency game mode ensures synchronized audio during mobile gaming, while the 35-hour total battery life (7 hours earbuds + 28 hours case) keeps you connected all week. With IPX5 water resistance, intuitive touch controls, USB-C fast charging, and a compact charging case with LED indicator. Compatible with the itel Audio app for EQ customization. Brand new, sealed with full itel Nigeria warranty.', 1, 1718400000, 1, 19000, '/assets/products/itel-buds-5-anc-new.webp', 22000, 4.3, 0, 'itel', 0, 1, 'gadgets');

-- Oraimo FreePods 4 (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-freepods-4-new', 'Oraimo FreePods 4 True Wireless Earbuds - Brand New - ANC, 40H Battery, IPX5', 'audio', 85000, 85000, 72000, 15, 0.048, '/assets/products/oraimo-freepods-4-new.webp', 'The Oraimo FreePods 4 deliver premium true wireless audio with Active Noise Cancellation and Transparency mode. The 10mm dynamic drivers with composite diaphragms produce rich, balanced sound with Oraimo signature Bass+ technology, while the ANC system blocks up to 30dB of ambient noise. The 60ms low-latency game mode ensures synchronized audio during competitive mobile gaming, and the 4-mic ENC technology guarantees crystal-clear calls in noisy environments. With 40 hours of total battery life (8 hours earbuds + 32 hours case), IPX5 water resistance, wireless charging case, and the Oraimo Sound app for EQ customization, these earbuds rival options three times their price. Google Fast Pair for instant Android connection. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 72000, '/assets/products/oraimo-freepods-4-new.webp', 78000, 4.7, 1, 'Oraimo', 1, 1, 'gadgets');

-- Oraimo TWS ANC Earbuds (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-tws-anc-earbuds-new', 'Oraimo True Wireless ANC Earbuds - Brand New - Hybrid ANC, 30H Battery, ENC Calls', 'audio', 45000, 45000, 35000, 18, 0.045, '/assets/products/oraimo-tws-anc-earbuds-new.webp', 'The Oraimo True Wireless ANC Earbuds bring active noise cancellation to the accessible tier. Featuring 10mm dynamic drivers, hybrid ANC technology that reduces up to 28dB of ambient noise, and Environmental Noise Cancellation for clear calls, these earbuds create a personal bubble of immersive sound. The touch controls, 30-hour total battery life with the charging case, and IPX4 sweat resistance make them perfect for commuting, workouts, and focused work sessions. With Bluetooth 5.3 for stable connectivity, 60ms gaming mode, and the Oraimo Sound app for customizable EQ, premium audio is now within everyone reach. USB-C fast charging delivers 2 hours playback from 10 minutes charge. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 35000, '/assets/products/oraimo-tws-anc-earbuds-new.webp', 40000, 4.5, 1, 'Oraimo', 1, 1, 'gadgets');

-- Oraimo Neckband Bluetooth Earphones (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-neckband-earphones-new', 'Oraimo Neckband Bluetooth Earphones - Brand New - 22H Battery, IPX5, Magnetic Earbuds', 'audio', 25000, 25000, 19000, 25, 0.035, '/assets/products/oraimo-neckband-earphones-new.webp', 'The Oraimo Neckband Bluetooth Earphones combine the convenience of wireless audio with the security of a neck-worn design. The flexible, skin-friendly silicone neckband ensures your earbuds are always within reach, while the 10mm dynamic drivers deliver punchy bass and clear mids. The magnetic earbuds snap together to pause music and auto-answer calls. With 22 hours of continuous playback, IPX5 water resistance, Bluetooth 5.3, and USB-C fast charging (10 minutes = 3 hours), these are the perfect workout and commute companions. The built-in vibration alert for incoming calls ensures you never miss important notifications. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 19000, '/assets/products/oraimo-neckband-earphones-new.webp', 22000, 4.4, 0, 'Oraimo', 1, 0, 'gadgets');

-- Oraimo Bluetooth Speaker 20W (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-bluetooth-speaker-20w-new', 'Oraimo Bluetooth Speaker 20W - Brand New - IPX6, 12H Battery, TWS Pairing, Deep Bass', 'audio', 55000, 55000, 45000, 12, 0.55, '/assets/products/oraimo-bluetooth-speaker-20w-new.webp', 'The Oraimo Bluetooth Speaker 20W delivers room-filling 360-degree sound in a compact, portable package. Featuring dual full-range drivers with dual passive bass radiators, this speaker produces surprisingly deep bass and crisp highs with 20W total output. The IPX6 water resistance handles poolside splashes and rain, while the 12-hour battery life ensures all-day soundtracking. With Bluetooth 5.3 for stable connectivity up to 30m range, TWS pairing for true stereo sound with a second speaker, and a built-in microphone for hands-free calls, this speaker punches well above its weight class. USB-C charging, AUX input, and microSD card slot for versatile playback. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 45000, '/assets/products/oraimo-bluetooth-speaker-20w-new.webp', 50000, 4.5, 1, 'Oraimo', 1, 1, 'gadgets');

