VALUES ('itel-130w-power-station-new', 'itel 130W Portable Power Station - Brand New - 150Wh, AC/DC/USB, Solar Ready', 'power-stations', 135000, 135000, 115000, 6, 2.50, '/assets/products/itel-130w-power-station-new.webp', 'The itel 130W Portable Power Station is a compact energy hub for outdoor adventures and emergency backup. Featuring a 150Wh lithium-ion battery with 130W AC outlet (pure sine wave), 2x USB-C (60W PD), 2x USB-A (18W QC), and 12V DC car port. Charges via wall outlet (4 hours), car (5 hours), or solar panel (sold separately). The LCD display shows input/output wattage and remaining battery. LED flashlight with SOS mode. Weighs just 2.5kg with integrated carry handle. Perfect for camping, fieldwork, light home backup, and keeping essential devices powered during NEPA outages. Brand new, sealed with full itel Nigeria warranty.', 1, 1718400000, 1, 115000, '/assets/products/itel-130w-power-station-new.webp', 125000, 4.4, 1, 'itel', 1, 1, 'gadgets');

