-- itel Smart TV Remote (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('itel-smart-tv-remote-new', 'itel Smart TV Remote - Brand New - Universal, Infrared, Netflix/YouTube Shortcuts', 'accessories', 9000, 9000, 6800, 30, 0.06, '/assets/products/itel-smart-tv-remote-new.webp', 'The itel Smart TV Remote is a universal replacement controller engineered for seamless compatibility with most major television brands, Android TV boxes, and streaming devices. Featuring an ergonomically sculpted body with anti-slip texture, responsive rubber dome switches, and optimally spaced buttons, this remote restores full command of your entertainment ecosystem. Dedicated shortcut keys for Netflix, YouTube, and popular streaming apps provide one-touch access to your favorite content. The robust IR blaster delivers strong, reliable signal transmission across large living rooms, while the lightweight construction ensures comfortable extended browsing. Requires 2x AAA batteries (not included). Brand new, sealed with full itel Nigeria warranty.', 1, 1718400000, 1, 6800, '/assets/products/itel-smart-tv-remote-new.webp', 8000, 4.2, 0, 'itel', 0, 0, 'gadgets');

