-- itel Smart Watch 1 (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('itel-smart-watch-1-new', 'itel Smart Watch 1 - Brand New - 1.83" HD, Heart Rate, SpO2, IP67, 10-Day Battery', 'wearables', 18000, 18000, 14000, 20, 0.038, '/assets/products/itel-smart-watch-1-new.webp', 'The itel Smart Watch 1 is your affordable gateway to wearable technology. Featuring a vibrant 1.83-inch HD color touch display with 240x284 resolution, this watch monitors heart rate, tracks steps, calories, and 50+ sports modes to keep your fitness journey on track. Receive call, message, and app notifications directly on your wrist, while the camera remote, music controls, and find-my-phone feature add everyday convenience. With 10-day battery life, IP67 water resistance, and interchangeable straps, this smartwatch proves that advanced technology does not require a premium price. Compatible with both Android and iOS via the itel Wear app. Brand new, sealed with full itel Nigeria warranty.', 1, 1718400000, 1, 14000, '/assets/products/itel-smart-watch-1-new.webp', 16000, 4.2, 0, 'itel', 0, 1, 'gadgets');

-- Oraimo Smart Watch (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('oraimo-smart-watch-new', 'Oraimo Smart Watch - Brand New - 1.85" AMOLED, Bluetooth Calling, IP68, 7-Day Battery', 'wearables', 38000, 38000, 30000, 18, 0.045, '/assets/products/oraimo-smart-watch-new.webp', 'The Oraimo Smart Watch is your personal health and productivity companion. Featuring a vibrant 1.85-inch AMOLED Always-On display with 1000 nits brightness, this watch tracks heart rate, blood oxygen (SpO2), sleep patterns, and over 100 sports modes with precision. Bluetooth calling with built-in speaker and microphone enables hands-free conversations. Receive notifications, control music, and capture photos remotely from your wrist. The IP68 water resistance handles swimming and workouts, while the 7-day battery life (14-day standby) ensures continuous health monitoring with magnetic charging. Customizable watch faces via the Oraimo Wear app. Premium zinc alloy frame with comfortable silicone strap in Midnight Black, Silver, or Rose Gold. Brand new, sealed with full Oraimo Nigeria warranty.', 1, 1718400000, 1, 30000, '/assets/products/oraimo-smart-watch-new.webp', 34000, 4.5, 1, 'Oraimo', 1, 1, 'gadgets');
